const rtdal002354Source0015 = `test_that("multiple aesthetics can be set with one function call", {
  df <- data_frame(
    x = LETTERS[1:3],
    y = LETTERS[4:6]
  )
  p <- ggplot(df, aes(x, y, colour = x, fill = y)) +
    scale_colour_manual(
      values = c("grey20", "grey40", "grey60", "red", "green", "blue"),
      aesthetics = c("colour", "fill")
    )

  expect_equal(get_layer_data(p)$colour, c("grey20", "grey40", "grey60"))
  expect_equal(get_layer_data(p)$fill, c("red", "green", "blue"))

  # color order is determined by data order, and breaks are combined where possible
  df <- data_frame(
    x = LETTERS[1:3],
    y = LETTERS[2:4]
  )
  p <- ggplot(df, aes(x, y, colour = x, fill = y)) +
    scale_colour_manual(
      values = c("cyan", "red", "green", "blue"),
      aesthetics = c("fill", "colour")
    )

  expect_equal(get_layer_data(p)$colour, c("cyan", "red", "green"))
  expect_equal(get_layer_data(p)$fill, c("red", "green", "blue"))
})`

const rtdal002354Source0016 = `test_that("limits with NA are replaced with the min/max of the data for continuous scales", {
  make_scale <- function(limits = NULL, data = NULL) {
    scale <- continuous_scale("aesthetic", palette = identity, limits = limits)
    if (!is.null(data)) {
      scale$train(data)
    }
    scale
  }

  # emptiness
  expect_true(make_scale()$is_empty())
  expect_false(make_scale(limits = c(0, 1))$is_empty())
  expect_true(make_scale(limits = c(0, NA))$is_empty())
  expect_true(make_scale(limits = c(NA, NA))$is_empty())
  expect_true(make_scale(limits = c(NA, 0))$is_empty())

  # limits
  expect_equal(make_scale(data = 1:5)$get_limits(), c(1, 5))
  expect_equal(make_scale(limits = c(1, 5))$get_limits(), c(1, 5))
  expect_equal(make_scale(limits = c(NA, NA))$get_limits(), c(0, 1))
  expect_equal(make_scale(limits = c(NA, NA), data = 1:5)$get_limits(), c(1, 5))
  expect_equal(make_scale(limits = c(1, NA), data = 1:5)$get_limits(), c(1, 5))
  expect_equal(make_scale(limits = c(NA, 5), data = 1:5)$get_limits(), c(1, 5))
})`

const rtdal002354Source0017 = "test_that(\"scale_apply preserves class and attributes\", {\n  df <- data_frame(\n    x = structure(c(1, 2), foo = \"bar\", class = c(\"baz\", \"numeric\")),\n    y = c(1, 1),\n    z = c(\"A\", \"B\")\n  )\n\n  # Functions to make the 'baz'-class more type stable\n  `c.baz` <- function(...) {\n    dots <- list(...)\n    attris <- attributes(dots[[1]])\n    x <- do.call(\"c\", lapply(dots, unclass))\n    attributes(x) <- attris\n    x\n  }\n  `[.baz` <- function(x, i) {\n    attris <- attributes(x)\n    x <- unclass(x)[i]\n    attributes(x) <- attris\n    x\n  }\n\n  plot <- ggplot(df, aes(x, y)) +\n    scale_x_continuous() +\n    # Facetting such that 2 x-scales will exist, i.e. `x` will be subsetted\n    facet_grid(~ z, scales = \"free_x\")\n  plot <- ggplot_build(plot)\n\n  # Perform identity transformation via `scale_apply`\n  out <- with_bindings(scale_apply(\n    df, \"x\", \"transform\", 1:2, plot@layout$panel_scales_x\n  )[[1]], `c.baz` = `c.baz`, `[.baz` = `[.baz`, .env = global_env())\n\n  # Check that it errors on bad scale ids\n  expect_snapshot_error(scale_apply(\n    df, \"x\", \"transform\", c(NA, 1), plot@layout$panel_scales_x\n  ))\n\n  # Check class preservation\n  expect_s3_class(out, \"baz\")\n  expect_s3_class(out, \"numeric\")\n\n  # Check attribute preservation\n  expect_identical(attr(out, \"foo\"), \"bar\")\n\n  # Negative control: non-type stable classes don't preserve attributes\n  class(df$x) <- \"foobar\"\n\n  out <- with_bindings(scale_apply(\n    df, \"x\", \"transform\", 1:2, plot@layout$panel_scales_x\n  )[[1]], `c.baz` = `c.baz`, `[.baz` = `[.baz`, .env = global_env())\n\n  expect_false(inherits(out, \"foobar\"))\n  expect_null(attributes(out))\n})"

const rtdal002354Source0018 = `test_that("All scale_colour_*() have their American versions", {
  # In testthat, the package env contains non-exported functions as well so we
  # need to parse NAMESPACE file by ourselves
  exports <- readLines(system.file("NAMESPACE", package = "ggplot2"))
  colour_scale_exports <- grep("export\\(scale_colour_.*\\)", exports, value = TRUE)
  color_scale_exports <- grep("export\\(scale_color_.*\\)", exports, value = TRUE)
  expect_equal(
    colour_scale_exports,
    sub("color", "colour", color_scale_exports)
  )
})`

const rtdal002354Source0019 = `test_that("scales accept lambda notation for function input", {
  check_lambda <- function(items, ggproto) {
    vapply(items, function(x) {
      f <- environment(ggproto[[x]])$f
      is_lambda(f)
    }, logical(1))
  }

  # Test continuous scale
  scale <- scale_fill_gradient(
    limits = ~ .x + c(-1, 1),
    breaks = ~ seq(.x[1], .x[2], by = 2),
    minor_breaks = ~ seq(.x[1], .x[2], by = 1),
    labels = ~ toupper(.x),
    rescaler = ~ rescale_mid(.x, mid = 0),
    oob = ~ oob_squish(.x, .y, only.finite = FALSE)
  )
  check <- check_lambda(
    c("limits", "breaks", "minor_breaks", "labels", "rescaler"),
    scale
  )
  expect_true(all(check))

  # Test discrete scale
  scale <- scale_x_discrete(
    limits = ~ rev(.x),
    breaks = ~ .x[-1],
    labels = ~ toupper(.x)
  )
  check <- check_lambda(c("limits", "breaks", "labels"), scale)
  expect_true(all(check))

  # Test binned scale
  scale <- scale_fill_steps(
    limits = ~ .x + c(-1, 1),
    breaks = ~ seq(.x[1], .x[2], by = 2),
    labels = ~ toupper(.x),
    rescaler = ~ rescale_mid(.x, mid = 0),
    oob = ~ oob_squish(.x, .y, only.finite = FALSE)
  )
  check <- check_lambda(
    c("limits", "breaks", "labels", "rescaler"),
    scale
  )
  expect_true(all(check))
})`

