const rtdal002377Source0030 = "test_that(\"complete_theme completes a theme\", {\n  # `NULL` should match default\n  gray <- theme_gray()\n  new <- complete_theme(NULL, default = gray)\n  expect_equal(S7::S7_data(new), S7::S7_data(gray))\n\n  # Elements are propagated\n  new <- complete_theme(theme(axis.line = element_line(\"red\")), gray)\n  expect_equal(new$axis.line@colour, \"red\")\n\n  # Missing elements are filled in if default theme is incomplete\n  new <- complete_theme(default = theme())\n  expect_s3_class(new$axis.line, \"ggplot2::element_blank\")\n\n  # Registered elements are included\n  register_theme_elements(\n    test = element_text(),\n    element_tree = list(test = el_def(element_text, \"text\"))\n  )\n  new <- complete_theme(default = gray)\n  expect_s3_class(new$test, \"ggplot2::element_text\")\n  reset_theme_settings()\n})"

const rtdal002377Source0031 = `test_that("panel.widths and panel.heights works with free-space panels", {

  df <- data.frame(x = c(1, 1, 2, 1, 3), g = c("A", "B", "B", "C", "C"))

  p <- ggplotGrob(
    ggplot(df, aes(x, x)) +
      geom_point() +
      scale_x_continuous(expand = expansion(add = 1)) +
      facet_grid(~ g, scales = "free_x", space = "free_x") +
      theme(
        panel.widths = unit(11, "cm"),
        panel.spacing.x = unit(1, "cm")
      )
  )

  idx <- range(panel_cols(p)$l)
  expect_equal(as.numeric(p$widths[seq(idx[1], idx[2])]), c(2, 1, 3, 1, 4))

  p <- ggplotGrob(
    ggplot(df, aes(x, x)) +
      geom_point() +
      scale_y_continuous(expand = expansion(add = 1)) +
      facet_grid(g ~ ., scales = "free_y", space = "free_y") +
      theme(
        panel.heights = unit(11, "cm"),
        panel.spacing.y = unit(1, "cm")
      )
  )

  idx <- range(panel_rows(p)$t)
  expect_equal(as.numeric(p$heights[seq(idx[1], idx[2])]), c(2, 1, 3, 1, 4))

})`

