const rtdal002395Source0001 = "glue_sql <- function(\n  ...,\n  .con,\n  .sep = \"\",\n  .envir = parent.frame(),\n  .open = \"{\",\n  .close = \"}\",\n  .na = DBI::SQL(\"NULL\"),\n  .null = character(),\n  .comment = \"#\",\n  .literal = FALSE,\n  .trim = TRUE\n) {\n  if (missing(.con)) {\n    stop(\"`.con` is absent but must be supplied.\")\n  }\n\n  DBI::SQL(glue(\n    ...,\n    .sep = .sep,\n    .envir = .envir,\n    .open = .open,\n    .close = .close,\n    .na = .na,\n    .null = .null,\n    .comment = .comment,\n    .literal = .literal,\n    .transformer = sql_quote_transformer(.con, .na),\n    .trim = .trim\n  ))\n}"

