const rtdal002396Source0002 = `with_glue_error <- function(expr, message) {
  if (!requireNamespace("rlang", quietly = TRUE)) {
    return(expr)
  }

  withCallingHandlers(
    expr,
    error = function(cnd) {
      rlang::abort(
        message,
        parent = cnd,
        call = NULL
      )
    }
  )
}`

