const rtdal002406Source0004 = `describe("glue_data_sql", {
  con <- DBI::dbConnect(RSQLite::SQLite(), ":memory:")
  on.exit(DBI::dbDisconnect(con))

  it("errors if no connection given", {
    expect_snapshot(glue_data_sql(mtcars, "{head(gear)*}"), error = TRUE)
  })
  it("collapses values if succeeded by a *", {
    var <- "foo"
    expect_identical(
      glue_data_sql(mtcars, "{head(gear)*}", .con = con),
      DBI::SQL("4, 4, 4, 3, 3, 3")
    )
  })
})`

