				runtime.MustReplace(ctx, env, "D", []runtime.Value{runtime.MustCallIn(ctx, env, "==", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "D")), runtime.PrimitiveArg(runtime.NumericVector(0)))}, runtime.NumericVector(1e-10))
