const rtdal002524Source0011 = `.stop_not_number <- function(x,
                             ...,
                             exit_code,
                             allow_decimal,
                             min,
                             max,
                             allow_na,
                             allow_null,
                             arg,
                             call) {
  if (exit_code == IS_NUMBER_oob) {
    min <- min %||% -Inf
    max <- max %||% Inf

    if (min > -Inf && max < Inf) {
      what <- sprintf("a number between %s and %s", min, max)
    } else if (x < min) {
      what <- sprintf("a number larger than %s", min)
    } else if (x > max) {
      what <- sprintf("a number smaller than %s", max)
    } else {
      abort("Unexpected state in OOB check", .internal = TRUE)
    }
  } else if (allow_decimal) {
    what <- "a number"
  } else {
    what <- "a whole number"
  }

  stop_input_type(
    x,
    what,
    ...,
    allow_na = allow_na,
    allow_null = allow_null,
    arg = arg,
    call = call
  )
}`

