const rtdal002529Source0004 = "compare_unit <- function(x, y, comp = `=`) {\n  if (length(y) == 0) return(x)\n  if (length(x) == 0) return(y)\n  if (getRversion() >= \"3.6\" && (is.list(x) || is.list(y))) {\n    if (identical(comp, pmin)) {\n      return(unit.pmin(x, y))\n    }\n    if (identical(comp, pmax)) {\n      return(unit.pmax(x, y))\n    }\n    cli::cli_abort('comparison not supported')\n  }\n  # Below should be removed once the old grid unit implementation has been deprecated\n  x_attr <- attributes(x)\n  x_val <- unclass(x)\n  y_val <- unclass(y)\n\n  x_unit <- x_attr$unit\n  y_unit <- attr(x, \"unit\")\n\n  if (!all(x_unit == y_unit)) {\n    cli::cli_abort(\"comparison of units with different types currently not supported\")\n  }\n\n  `attributes<-`(comp(x_val, y_val), x_attr)\n}"

const rtdal002529Source0005 = `insert.unit <- function(x, values, after = length(x)) {
  lengx <- length(x)
  if (lengx == 0) return(values)
  if (length(values) == 0) return(x)

  if (after <= 0) {
    unit.c(values, x)
  } else if (after >= lengx) {
    unit.c(x, values)
  } else {
    unit.c(x[1L:after], values, x[(after + 1L):lengx])
  }
}`

const rtdal002529Source0006 = `"%||%" <- function(a, b) {
  if (!is.null(a)) a else b
}`

const rtdal002529Source0007 = `width_cm <- function(x) {
  if (is.grob(x)) {
    convertWidth(grobWidth(x), "cm", TRUE)
  } else if (is.list(x)) {
    vapply(x, width_cm, numeric(1))
  } else if (is.unit(x)) {
    convertWidth(x, "cm", TRUE)
  } else {
    cli::cli_abort("Unknown input")
  }
}`

